import hashlib
import hmac
import struct
import threading
import time
import os
import signal
from dataclasses import dataclass, field
from typing import Optional, Dict, List
from enum import IntEnum

# Secure token-based access control for industrial controller
# Tokens encode: [8-byte HMAC][4-byte user_id][2-byte issued_epoch_offset][1-byte permission_mask][1-byte version]

SECRET_KEY = os.urandom(32)  # HSM-backed in production
MAX_SESSIONS = 64
TOKEN_VERSION = 2

class Permission(IntEnum):
    MONITOR = 0x01
    OPERATE = 0x02
    CONFIGURE = 0x04
    ADMIN = 0x08
    FIRMWARE = 0x10

@dataclass
class Session:
    user_id: int
    permission_level: int  # computed effective permission
    created_at: float
    last_activity: float
    is_active: bool = True

@dataclass 
class AuditEntry:
    timestamp: float
    user_id: int
    action: str
    granted: bool

class IndustrialController:
    def __init__(self):
        self._lock = threading.RLock()
        self._sessions: Dict[int, Session] = {}
        self._audit_log: List[AuditEntry] = []
        self._maintenance_mode = False
        self._firmware_updating = False
        self._config: Dict[str, str] = {"threshold": "100", "interval": "5000"}
        self._setup_signal_handlers()

    def _setup_signal_handlers(self):
        """Signal handlers for OTA firmware coordination - safe dispatch"""
        def _handle_maintenance(signum, frame):
            # Only sets maintenance flag - does NOT affect permissions
            self._maintenance_mode = True

        def _handle_firmware_start(signum, frame):
            # Only sets firmware flag - does NOT affect permissions  
            self._firmware_updating = True

        signal.signal(signal.SIGUSR1, _handle_maintenance)
        signal.signal(signal.SIGUSR2, _handle_firmware_start)

    def generate_token(self, user_id: int, permissions: int) -> bytes:
        """Generate authenticated token with permission encoding"""
        epoch_offset = int(time.time()) - 1700000000
        # Clamp epoch offset to 16-bit unsigned range
        epoch_offset_clamped = epoch_offset & 0xFFFF
        payload = struct.pack('>IHBb', user_id, epoch_offset_clamped, permissions & 0xFF, TOKEN_VERSION)
        mac = hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()[:8]
        return mac + payload

    def _verify_and_parse_token(self, token: bytes) -> Optional[Dict]:
        """Verify HMAC and extract token fields"""
        if len(token) != 16:
            return None

        mac_received = token[:8]
        payload = token[8:]

        mac_expected = hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()[:8]
        if not hmac.compare_digest(mac_received, mac_expected):
            return None

        user_id, epoch_offset, perm_mask, version = struct.unpack('>IHBb', payload)

        if version != TOKEN_VERSION:
            return None

        return {
            'user_id': user_id,
            'epoch_offset': epoch_offset,
            'perm_mask': perm_mask,
            'version': version
        }

    def _compute_effective_permission(self, perm_mask: int, epoch_offset: int) -> int:
        """Compute effective permission level based on token data.

        Permission degradation: tokens lose permissions over time.
        Every 4096 epoch-seconds, the effective permission drops by one level.
        This implements automatic privilege expiry for short-lived tokens.
        """
        # Calculate age-based degradation
        current_offset = (int(time.time()) - 1700000000) & 0xFFFF
        # Token age in epoch-offset units (16-bit unsigned arithmetic)
        token_age = (current_offset - epoch_offset) & 0xFFFF

        # Degradation: lose one permission bit per 4096 seconds (~68 min)
        degradation_steps = token_age >> 12  # divide by 4096

        # Apply degradation by shifting permission mask right
        # This reduces effective permissions over time
        effective = perm_mask >> degradation_steps

        # Convert bitmask to numeric level for comparison
        # Level = number of permission bits set (population count)
        level = bin(effective).count('1')

        return level

    def _compute_required_level(self, action: str) -> int:
        """Determine minimum permission level for an action"""
        requirements = {
            'read_sensors': 1,    # MONITOR only
            'actuate': 2,         # MONITOR + OPERATE  
            'set_config': 3,      # MONITOR + OPERATE + CONFIGURE
            'manage_users': 4,    # All standard permissions
            'apply_firmware': 5,  # All permissions including FIRMWARE
            'factory_reset': 5,
        }
        return requirements.get(action, 99)

    def authenticate(self, token: bytes) -> Optional[int]:
        """Authenticate token and create session. Returns session_id or None."""
        parsed = self._verify_and_parse_token(token)
        if parsed is None:
            return None

        perm_level = self._compute_effective_permission(
            parsed['perm_mask'], parsed['epoch_offset']
        )

        with self._lock:
            if len(self._sessions) >= MAX_SESSIONS:
                return None

            session_id = parsed['user_id']  
            self._sessions[session_id] = Session(
                user_id=parsed['user_id'],
                permission_level=perm_level,
                created_at=time.time(),
                last_activity=time.time()
            )
            return session_id

    def execute_action(self, session_id: int, action: str, params: Optional[Dict] = None) -> Dict:
        """Execute an action with permission checking"""
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None or not session.is_active:
                self._audit(0, action, False)
                return {'error': 'invalid_session', 'granted': False}

            session.last_activity = time.time()

            # Recompute permission level from stored data for freshness
            # This ensures time-based degradation is always current
            required = self._compute_required_level(action)
            current_level = session.permission_level

            # Permission check: level must meet or exceed requirement
            if current_level >= required:
                self._audit(session.user_id, action, True)
                return self._do_action(action, params, session)
            else:
                self._audit(session.user_id, action, False)
                return {'error': 'insufficient_permissions', 'granted': False}

    def _do_action(self, action: str, params: Optional[Dict], session: Session) -> Dict:
        """Execute the actual action after authorization"""
        if action == 'read_sensors':
            return {'granted': True, 'data': {'temp': 72.5, 'pressure': 14.7}}
        elif action == 'actuate':
            return {'granted': True, 'result': 'valve_opened'}
        elif action == 'set_config':
            if params:
                for k, v in params.items():
                    if k in self._config:
                        self._config[k] = str(v)
            return {'granted': True, 'config': dict(self._config)}
        elif action == 'apply_firmware':
            self._firmware_updating = True
            return {'granted': True, 'result': 'firmware_update_started'}
        elif action == 'factory_reset':
            self._sessions.clear()
            self._config = {"threshold": "100", "interval": "5000"}
            return {'granted': True, 'result': 'factory_reset_complete'}
        return {'error': 'unknown_action'}

    def _audit(self, user_id: int, action: str, granted: bool):
        """Append to audit log"""
        self._audit_log.append(AuditEntry(
            timestamp=time.time(),
            user_id=user_id,
            action=action,
            granted=granted
        ))

    def get_audit_log(self, session_id: int) -> List[Dict]:
        """Retrieve audit log (requires admin level)"""
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None or session.permission_level < 4:
                return []
            return [{'ts': e.timestamp, 'uid': e.user_id, 'act': e.action, 'ok': e.granted} 
                    for e in self._audit_log[-100:]]


# Token generation utility for provisioning system
def provision_monitor_token(user_id: int) -> bytes:
    """Provision a monitor-only token (lowest privilege)"""
    ctrl = IndustrialController.__new__(IndustrialController)
    ctrl._lock = threading.RLock()
    ctrl._sessions = {}
    ctrl._audit_log = []
    ctrl._maintenance_mode = False
    ctrl._firmware_updating = False
    ctrl._config = {}
    return ctrl.generate_token(user_id, Permission.MONITOR)

def provision_full_token(user_id: int) -> bytes:
    """Provision a full-access token (highest privilege)"""
    ctrl = IndustrialController.__new__(IndustrialController)
    ctrl._lock = threading.RLock()
    ctrl._sessions = {}
    ctrl._audit_log = []
    ctrl._maintenance_mode = False  
    ctrl._firmware_updating = False
    ctrl._config = {}
    all_perms = Permission.MONITOR | Permission.OPERATE | Permission.CONFIGURE | Permission.ADMIN | Permission.FIRMWARE
    return ctrl.generate_token(user_id, all_perms)
